SELECT /*+ MAX_EXECUTION_TIME(5000) */ strategy_id, CASE WHEN strategy_name REGEXP '[0-9]{7,}|[0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}|@|://' THEN CONCAT('<已屏蔽:', CHAR_LENGTH(strategy_name), '字符>') ELSE strategy_name END AS strategy_name_m, status, result_code, exec_priority, scene_id, strategy_express, create_time, update_time FROM luckyus_iriskcontrolservice.t_rms_engine_strategy WHERE strategy_id LIKE 'strategy_eoHQ6Qs_FRqp' OR strategy_id = 'strategy_E1HJJyHuyevm'
